$ErrorActionPreference = 'Stop'
$cfg = @{}
Get-Content -LiteralPath '.env' | ForEach-Object {
  if ($_ -match '^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$') { $cfg[$matches[1]] = $matches[2].Trim().Trim('"').Trim("'") }
}
$sshTarget = $cfg['JI_TEST_SSH_TARGET']
$sshKey = $cfg['JI_TEST_SSH_KEY']
$archive = '/export/user\.gold-band\projects\e-projects-code-ai-ji--a40d4379\tasks\task-015\runs\run-001\rounds\round-001\nodes\ai-dynamic\attempt-001\dynamic\nodes\phase-2-parallel-capabilities-merge\attempt-001\attachments\stage2-linux-source.tgz'
& ssh -i $sshKey -o BatchMode=yes -o StrictHostKeyChecking=yes -- $sshTarget 'set -eu; root=/home/ubuntu/.ji-stage2-validation/run-001; test "$(realpath -m -- "$root")" = "$root"; test ! -e "$root/source-v2"; mkdir "$root/source-v2"'
if ($LASTEXITCODE -ne 0) { throw "Remote source-v2 creation failed: $LASTEXITCODE" }
& scp -q -i $sshKey -o BatchMode=yes -o StrictHostKeyChecking=yes -- $archive ($sshTarget + ':/home/ubuntu/.ji-stage2-validation/run-001/source-v2.tgz')
if ($LASTEXITCODE -ne 0) { throw "Linux source-v2 upload failed: $LASTEXITCODE" }
& ssh -i $sshKey -o BatchMode=yes -o StrictHostKeyChecking=yes -- $sshTarget 'set -eu; root=/home/ubuntu/.ji-stage2-validation/run-001; actual=$(sha256sum "$root/source-v2.tgz" | cut -d " " -f 1); test "$actual" = cf193b3e68ff3b7f37290ae274888671004a97d2f94c21af12ab800462b48a39; tar -xzf "$root/source-v2.tgz" -C "$root/source-v2"; chmod u+x "$root/source-v2/gradlew" "$root/source-v2/scripts/"*.sh; printf "linux_source_v2_ready sha256=%s\n" "$actual"'
if ($LASTEXITCODE -ne 0) { throw "Linux source-v2 verification failed: $LASTEXITCODE" }

